def source_geometry(tree,inp,*,expected_order=None):
    g=Nodes(tree)
    info=g.node('GeometryNodeCollectionInfo','Actual editable source objects');info.transform_space='RELATIVE'
    info.inputs['Separate Children'].default_value=True;info.inputs['Reset Children'].default_value=False
    g.link(inp.outputs['Source Objects'],info.inputs['Collection'])
    realize=g.node('GeometryNodeRealizeInstances','Read live authored meshes');g.link(info.outputs['Instances'],realize.inputs['Geometry'])
    join=g.node('GeometryNodeJoinGeometry','Authored objects and optional controller base mesh')
    g.link(realize.outputs['Geometry'],join.inputs['Geometry']);g.link(inp.outputs['Geometry'],join.inputs['Geometry'])
    inverse=g.node('ShaderNodeMath','Blender units to metres');inverse.operation='DIVIDE';inverse.inputs[0].default_value=1
    g.link(inp.outputs['Metres to Blender Units'],inverse.inputs[1])
